variants.result_local:
int far f(int p1, int x1, int y1, int p2, int x2, int y2)
{
    int r;

    if (p1 <= 1) {
        if (p2 <= 1)
            r = g(p1, x1, y1, x2, y2);
        else
            r = g(p1, x1, y1, A[0], A[1]);
    } else if (p2 == p1)
        r = g(p1, x1, y1, x2, y2);
    else
        r = g(p1, x1, y1, B[0], B[1]);
    return r;
}

variants.direct_return:
int far f(int p1, int x1, int y1, int p2, int x2, int y2)
{
    if (p1 <= 1) {
        if (p2 <= 1)
            return g(p1, x1, y1, x2, y2);
        return g(p1, x1, y1, A[0], A[1]);
    }
    if (p2 == p1)
        return g(p1, x1, y1, x2, y2);
    return g(p1, x1, y1, B[0], B[1]);
}
